/bin/bash -lc "python - <<'PY'
import re,json,glob
s=open('outputs/grpo/train.log').read(); rows=[]
for l in s.splitlines():
 if 'step:' not in l: continue
 d={k:float(v) for k,v in re.findall(r'([\\w/]+):(?:np\\.float64\\()?(-?[0-9]+(?:\\.[0-9]*)?(?:e[-+]?\\d+)?)',l)}
 if 'step' in d: rows.append(d)
keys=['critic/score/mean','actor/grad_norm','actor/ppo_kl','actor/pg_clipfrac','actor/entropy','response_length/mean','response_length/clip_ratio','timing_s/step']
for d in rows:
 if d['step'] in [1,20,40,50,59,60,65,70,72,75,78,80,84,90,150,300]: print(int(d['step']),{k:round(d.get(k,-1),5) for k in keys})
for f in sorted(glob.glob('outputs/grpo/rollouts/*'),key=lambda p:int(p.split('/')[-1].split('.')[0])):
 a=[json.loads(l) for l in open(f)];print(f,len(a),sum(x['score'] for x in a));print(a[0]['output'][:300])
PY"

